SELECT COUNT(*) FROM sensitivitydata;
SELECT COUNT(DISTINCT sd.artref) FROM sensitivitydata sd JOIN artifactscore a ON sd.artref = a.artregistry;

-- Check sample values for other sensitivity columns
SELECT tempsensitivity, humiditysensitivity, vibrasensitivity 
FROM sensitivitydata LIMIT 5;

-- Check all columns across all tables for anything related to visible exposure
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%visib%' OR column_name LIKE '%expos%' OR column_name LIKE '%lux%';

-- Let me check if there's a 1:1 relationship between artifacts and conditionassessments
SELECT COUNT(*) FROM conditionassessments;
SELECT COUNT(DISTINCT artrefexamined) FROM conditionassessments;

